// Standalone test harness for ariston_passive_core.{h,cpp} -- plain g++,
// no ESPHome/Arduino dependency, so these are real numbers from the actual
// component logic, not a design narrative. Run via run_tests.sh.
//
// All test data in Part 1 is FULLY SYNTHETIC -- generated by
// generate_synthetic_streams.py from this project's own documented protocol
// rules (framing/checksum/register addresses), not derived from or copied
// from any real captured device traffic. This project's private development
// additionally validated this same core logic against 2,675 real,
// third-party-captured Velis 80 frames -- that data is NOT included in this
// repository (see test/README.md for why) and that historical result is
// documented there as context, not reproduced or re-asserted by this file.
// Part 2 is a set of small, self-contained synthetic edge-case checks that
// never depended on any external data file.
#include "../firmware/core/ariston_passive_core.h"
#include <cstdio>
#include <cstdint>
#include <cmath>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <algorithm>
#include <map>
#include <set>

using namespace ariston_passive;

struct StreamFrame {
  double ts_ms;
  std::vector<uint8_t> bytes;
};

static std::vector<StreamFrame> load_stream(const std::string &path) {
  std::vector<StreamFrame> out;
  std::ifstream f(path);
  std::string line;
  while (std::getline(f, line)) {
    if (line.empty()) continue;
    std::istringstream iss(line);
    double ts;
    iss >> ts;
    StreamFrame sf;
    sf.ts_ms = ts;
    std::string tok;
    while (iss >> tok) sf.bytes.push_back((uint8_t)std::stoul(tok, nullptr, 16));
    out.push_back(sf);
  }
  return out;
}

struct MergedEvent {
  double ts_ms;
  bool is_request;  // true = request (gateway->MCU) stream, false = response
  const std::vector<uint8_t> *bytes;
};

static int g_fail = 0;
static int g_pass = 0;
#define CHECK(cond, msg)                                                \
  do {                                                                  \
    if (cond) {                                                         \
      g_pass++;                                                         \
      std::printf("  PASS: %s\n", msg);                                 \
    } else {                                                            \
      g_fail++;                                                         \
      std::printf("  FAIL: %s\n", msg);                                 \
    }                                                                   \
  } while (0)

// Replays one named scenario's request+response stream files (merged in
// timestamp order, exactly as a real two-wire passive CN6 tap would deliver
// bytes) through a caller-supplied PassiveMonitor, so each scenario below
// can attach whatever callbacks it needs before replay.
static void replay_scenario(const std::string &stream_dir, const std::string &stem, PassiveMonitor &mon) {
  auto req = load_stream(stream_dir + "/" + stem + "_request.txt");
  auto resp = load_stream(stream_dir + "/" + stem + "_response.txt");

  std::vector<MergedEvent> events;
  events.reserve(req.size() + resp.size());
  for (auto &f : req) events.push_back({f.ts_ms, true, &f.bytes});
  for (auto &f : resp) events.push_back({f.ts_ms, false, &f.bytes});
  std::stable_sort(events.begin(), events.end(), [](const MergedEvent &a, const MergedEvent &b) { return a.ts_ms < b.ts_ms; });

  for (auto &ev : events) {
    uint32_t now_ms = (uint32_t)std::lround(ev.ts_ms);
    for (uint8_t b : *ev.bytes) {
      if (ev.is_request)
        mon.feed_request_byte(b, now_ms);
      else
        mon.feed_response_byte(b, now_ms);
    }
  }
}

// --- Part 1: fully synthetic, fabricated scenarios ----------------------

static void test_synthetic_boot() {
  std::printf("\n--- synthetic_boot: handshake (uncorrelated) + 2 ordinary register reads ---\n");
  PassiveMonitor mon;
  int temp_count = 0, raw_count = 0;
  double last_temp = -1.0;
  mon.on_decoded_temperature = [&](uint16_t, double v, const char *) { temp_count++; last_temp = v; };
  mon.on_decoded_raw = [&](uint16_t, const std::vector<uint8_t> &, const char *) { raw_count++; };

  replay_scenario("streams_synthetic", "synthetic_boot", mon);

  CHECK(mon.request_frames_seen() == 3 && mon.request_frames_valid() == 3,
        "synthetic_boot: all 3 request frames (handshake + 2 reads) parse and checksum-validate");
  CHECK(mon.response_frames_seen() == 3 && mon.response_frames_valid() == 3,
        "synthetic_boot: all 3 response frames parse and checksum-validate");
  CHECK(raw_count == 1, "synthetic_boot: the power-register read decodes to exactly one raw (MATCHED_ENUM) publish");
  CHECK(temp_count == 1 && std::fabs(last_temp - 50.0) < 0.05,
        "synthetic_boot: the set-temperature read decodes to the fabricated 50.0C value");
}

static void test_synthetic_poll_cycle() {
  std::printf("\n--- synthetic_poll_cycle: 3 identical repeated cycles -> dedup + UNDECODED-register silence ---\n");
  PassiveMonitor mon;
  int temp_count = 0, raw_count = 0;
  std::set<uint16_t> temp_addrs, raw_addrs;
  bool saw_undecoded = false;
  mon.on_decoded_temperature = [&](uint16_t addr, double, const char *) { temp_count++; temp_addrs.insert(addr); if (addr == 0xD84B) saw_undecoded = true; };
  mon.on_decoded_raw = [&](uint16_t addr, const std::vector<uint8_t> &, const char *) { raw_count++; raw_addrs.insert(addr); if (addr == 0xD84B) saw_undecoded = true; };

  replay_scenario("streams_synthetic", "synthetic_poll_cycle", mon);

  CHECK(mon.request_frames_seen() == 21 && mon.request_frames_valid() == 21,
        "synthetic_poll_cycle: all 21 request frames (7 per cycle x 3 cycles) parse and checksum-validate");
  CHECK(mon.response_frames_seen() == 21 && mon.response_frames_valid() == 21,
        "synthetic_poll_cycle: all 21 response frames parse and checksum-validate");
  CHECK(temp_count == 6 && temp_addrs.size() == 6,
        "synthetic_poll_cycle: 6 distinct temperature registers (displayed temp + 5 tank addresses) each publish exactly once despite 3 identical repeated cycles");
  CHECK(raw_count == 4 && raw_addrs.size() == 4,
        "synthetic_poll_cycle: 4 distinct raw/enum registers (power/eco/anti-legionella/mode) each publish exactly once, same dedup behavior");
  CHECK(!saw_undecoded,
        "synthetic_poll_cycle: the UNDECODED register (0xD84B) is parsed/correlated but never published as a decoded value, in any of the 3 cycles");
}

static void test_synthetic_setpoint_transition() {
  std::printf("\n--- synthetic_setpoint_transition: fabricated 50.0C -> 55.0C -> 48.0C ---\n");
  PassiveMonitor mon;
  std::vector<double> sequence;
  mon.on_decoded_temperature = [&](uint16_t addr, double v, const char *) { if (addr == 0x2D79) sequence.push_back(v); };

  replay_scenario("streams_synthetic", "synthetic_setpoint_transition", mon);

  std::printf("  decoded sequence:");
  for (double v : sequence) std::printf(" %.1f", v);
  std::printf("\n");

  bool shape_ok = sequence.size() == 3
      && std::fabs(sequence[0] - 50.0) < 0.05
      && std::fabs(sequence[1] - 55.0) < 0.05
      && std::fabs(sequence[2] - 48.0) < 0.05;
  CHECK(shape_ok,
        "synthetic_setpoint_transition: decoder reproduces the fabricated 50.0C -> 55.0C -> 48.0C step sequence in order, "
        "with repeated same-value reads correctly deduped to one publish per step (deliberately different numbers from "
        "this project's own excluded real experiment and from the Evo reference project's published example, so this "
        "result cannot be mistaken for either)");
}

static void test_synthetic_corrupted_stream() {
  std::printf("\n--- synthetic_corrupted_stream: resync across corruption, garbage, and an interrupted frame ---\n");
  PassiveMonitor mon;
  int unmatched = 0;
  mon.on_unmatched_response = [&]() { unmatched++; };

  replay_scenario("streams_synthetic", "synthetic_corrupted_stream", mon);

  CHECK(mon.response_frames_seen() == 4,
        "synthetic_corrupted_stream: exactly 4 byte sequences complete frame parsing (2 clean + 1 corrupted-checksum + 1 "
        "clean after the gap; the truncated frame and the 5 raw garbage bytes never complete parsing at all, as expected)");
  CHECK(mon.response_frames_valid() == 3,
        "synthetic_corrupted_stream: 3 of those 4 are checksum-valid; the deliberately corrupted one is correctly flagged invalid");
  CHECK(unmatched == 3,
        "synthetic_corrupted_stream: all 3 valid frames correctly report as unmatched (no request was ever fed in this "
        "response-only scenario, so there is nothing to correlate against -- confirms that path doesn't misfire)");
}

// --- Part 2: synthetic malformed/interrupted-frame tests -----------------
// Self-contained since the prior pass wrote these -- never depended on any
// external data file, kept as-is.

static std::vector<uint8_t> make_frame(uint8_t id, uint8_t cmd, std::vector<uint8_t> payload) {
  std::vector<uint8_t> f = {HEADER_BYTE, id, cmd, (uint8_t)payload.size()};
  for (auto b : payload) f.push_back(b);
  uint8_t sum = 0;
  for (auto b : f) sum += b;
  f.push_back(sum);
  return f;
}

static void test_malformed_frames() {
  std::printf("\n=== Part 2: synthetic malformed / interrupted-frame handling (isolated unit tests) ===\n");

  // Good frame, a frame with a deliberately corrupted checksum, garbage
  // bytes, then another good frame -- verify corruption doesn't take out
  // the frame that follows it.
  {
    PassiveMonitor mon;
    int valid_count = 0, invalid_count = 0;
    mon.on_response_frame = [&](const Frame &f) { f.valid ? valid_count++ : invalid_count++; };

    auto good1 = make_frame(0x14, 0x25, {0x00, 0x00, 0x01, 0x00});
    auto bad = make_frame(0x14, 0x25, {0xFF, 0xFF, 0xFF, 0xFF});
    bad.back() ^= 0xFF;  // corrupt the checksum byte specifically
    std::vector<uint8_t> garbage = {0x11, 0x22, 0x33, 0x44, 0x55};
    auto good2 = make_frame(0x14, 0x25, {0x02, 0x03, 0x01, 0x00});

    uint32_t t = 1000;
    for (auto b : good1) mon.feed_response_byte(b, t++);
    for (auto b : bad) mon.feed_response_byte(b, t++);
    for (auto b : garbage) mon.feed_response_byte(b, t++);
    for (auto b : good2) mon.feed_response_byte(b, t++);

    CHECK(valid_count == 2, "two genuinely valid frames both recognised despite a corrupted frame and garbage in between");
    CHECK(invalid_count == 1, "the corrupted-checksum frame is flagged invalid, not silently accepted");
  }

  // Truncated/interrupted frame: header+id+cmd+len+partial payload, then a
  // long gap (> FRAME_TIMEOUT_MS), then a fresh valid frame -- the watchdog
  // should abandon the stuck frame and resync cleanly on the new one.
  {
    PassiveMonitor mon;
    int valid_count = 0, invalid_count = 0;
    mon.on_response_frame = [&](const Frame &f) { f.valid ? valid_count++ : invalid_count++; };

    std::vector<uint8_t> truncated = {HEADER_BYTE, 0x14, 0x25, 0x04, 0x00, 0x00};  // declares 4 payload bytes, only delivers 2, then stream goes quiet
    uint32_t t = 2000;
    for (auto b : truncated) mon.feed_response_byte(b, t++);

    t += FRAME_TIMEOUT_MS + 100;  // simulate a real gap in the serial data

    auto good = make_frame(0x14, 0x25, {0x02, 0x03, 0x01, 0x00});
    for (auto b : good) mon.feed_response_byte(b, t++);

    CHECK(valid_count == 1 && invalid_count == 0,
          "after an interrupted mid-frame stream (gap > FRAME_TIMEOUT_MS), the next valid frame is correctly resynced and decoded");
  }

  // Exact-duplicate frame within DUPLICATE_SUPPRESS_MS should not be
  // double-processed (no double sensor publish), even though it is still
  // counted in the raw seen/valid totals for diagnostics.
  {
    PassiveMonitor mon;
    int request_cb_count = 0;
    mon.on_request_frame = [&](const Frame &) { request_cb_count++; };

    auto frame = make_frame(0x41, 0x25, {0x79, 0x2D});
    uint32_t t = 3000;
    for (auto b : frame) mon.feed_request_byte(b, t);  // first copy
    for (auto b : frame) mon.feed_request_byte(b, t + 1);  // identical frame, 1ms later -- well inside DUPLICATE_SUPPRESS_MS

    CHECK(request_cb_count == 1, "an exact-duplicate frame arriving within DUPLICATE_SUPPRESS_MS is not re-processed a second time");
    CHECK(mon.request_frames_seen() == 2, "raw seen-count still reflects both physical frames for diagnostics, even though only one was acted on");
  }

  // Repeated *real* (non-duplicate-window) identical values should not
  // cause incorrect state changes -- i.e. publishing the same decoded value
  // twice should fire the callback once, not twice, confirming dedupe-by-
  // value works across the full request->response decode path.
  // Value 69.0C / 0x02B2 and address 0x2D79 match DeDaMrAz's own forum-
  // published example frame (C3 41 33 04 79 2D B2 02 95, cited with
  // attribution in PROTOCOL.md and in ariston_passive_core.cpp) -- that is
  // a short, already-public illustrative example the original poster
  // published themselves, not bulk private capture data, so reusing it here
  // with attribution is a different provenance case from the excluded
  // streams/ data discussed in test/README.md.
  {
    PassiveMonitor mon;
    int temp_publish_count = 0;
    mon.on_decoded_temperature = [&](uint16_t, double, const char *) { temp_publish_count++; };

    auto req = make_frame(0x41, 0x25, {0x79, 0x2D});       // request set_temperature (0x2D79)
    auto resp = make_frame(0x14, 0x25, {0xB2, 0x02, 0x00, 0x00});  // 0x02B2 = 690 -> 69.0C

    uint32_t t = 4000;
    for (auto b : req) mon.feed_request_byte(b, t);
    for (auto b : resp) mon.feed_response_byte(b, t + 20);
    t += 2000;  // well past the poll cycle's ~1.15s period, not a duplicate-suppress situation
    for (auto b : req) mon.feed_request_byte(b, t);
    for (auto b : resp) mon.feed_response_byte(b, t + 20);

    CHECK(temp_publish_count == 1, "an unchanged decoded value queried twice, far apart in time, is published once, not twice (value-level dedupe, not just timing-window dedupe)");
  }
}

int main() {
  std::printf("=== Part 1: replay of fully synthetic, fabricated UART scenarios (no real/private capture data) ===\n");
  test_synthetic_boot();
  test_synthetic_poll_cycle();
  test_synthetic_setpoint_transition();
  test_synthetic_corrupted_stream();
  test_malformed_frames();
  std::printf("\n=== RESULT: %d passed, %d failed ===\n", g_pass, g_fail);
  return g_fail == 0 ? 0 : 1;
}
